layers.vertex:
attribute vec3 aO, aV; attribute vec2 aT; uniform float uTime, uW; uniform vec2 uRes; varying float vF; varying vec2 vQ;
    vec3 sim(float t){ float k = 5., e = exp(-k*t); vec3 p = aO + aV*(1.-e)/k; p.y += 9.*((1.-e)/(k*k) - t/k); return p; }
    void main(){
      float age = uTime - aT.x; if (age < 0. || age > aT.y){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 ch = projectionMatrix*viewMatrix*vec4(sim(age),1.), ct = projectionMatrix*viewMatrix*vec4(sim(max(age-.03,0.)),1.);
      vec2 d = (ch.xy/ch.w - ct.xy/ct.w)*uRes; float L = length(d); vec2 dir = L > .5 ? d/L : vec2(1.,0.), nrm = vec2(-dir.y, dir.x);
      float s = position.y + .5; vec4 c = mix(ct, ch, s);
      c.xy += (nrm*position.x*uW*2. + dir*(s-.5)*uW)*2./uRes*c.w;
      gl_Position = c; vF = 1. - age/aT.y; vQ = vec2(position.x*2., s);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vF; varying vec2 vQ;
    void main(){ float a = exp(-vQ.x*vQ.x*3.)*vQ.y, c = exp(-vQ.x*vQ.x*14.)*vQ.y;
      gl_FragColor = vec4((uOrange*a*.9 + mix(uOrange, vec3(1.), .4)*c*.35*vF)*(.4 + .9*vF), 1.); }   // blood droplets, no gold

layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.70){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO, 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = 1.5; mv.xy += position.xy*S*.5;   // splash shown at half size (shape math stays in vP units)
      vP = position.xy*S; vU = u; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){
      // rupture: viscous blood splash. A metaball field: central blob + 9 thick streams ending in round heads that
      // slow down (ease-out), stretch thin and sag under gravity; some heads pinch off into droplets. Soft threshold = liquid edge.
      float t = vU/0.70;
      float g = 1. - pow(1. - clamp(vU/.2, 0., 1.), 3.), f = (1. - smoothstep(.55, 1., t))*(vU < .033 ? 1.5 : 1.);
      vec2 p = vP; float r = length(p);
      float F = exp(-dot(p, p)*22.)*1.3*(1. - .6*smoothstep(.1, .7, t));
      for (int i=0;i<9;i++){ float fi = float(i), h = fract(sin(fi*53.7)*4375.5);
        float ac = fi*.698 + h*.4 + .6; vec2 dir = vec2(cos(ac), sin(ac));
        float L = (.42 + .50*h)*g; vec2 sag = vec2(0., -.45*t*t*(.6 + h));
        vec2 mid = dir*L*.5 + sag*.3, head = dir*L + sag;
        float thin = 1. - .55*smoothstep(.25, .9, t);                                   // streams stretch thin
        vec2 pa = p; float k1 = clamp(dot(pa, mid)/max(dot(mid, mid), 1e-6), 0., 1.), d1 = length(pa - mid*k1);
        vec2 pb = p - mid, bb = head - mid; float k2 = clamp(dot(pb, bb)/max(dot(bb, bb), 1e-6), 0., 1.), d2 = length(pb - bb*k2);
        float rad1 = mix(.075, .045, k1)*thin, rad2 = mix(.045, .03, k2)*thin;
        F += exp(-pow(d1/rad1, 2.))*.9 + exp(-pow(d2/rad2, 2.))*.9;
        float rb = (.065 + .045*h)*(1. - .3*t);
        F += exp(-pow(length(p - head)/rb, 2.))*1.3;                                       // round heavy head
        vec2 dr = dir*L*1.3 + sag*1.7;                                                     // detached droplet
        F += exp(-pow(length(p - dr)/(rb*.6), 2.))*step(.45, h)*smoothstep(.15, .35, t)*1.2; }
      float body = smoothstep(.5, .8, F);                                                  // soft liquid edge
      float thick = smoothstep(.9, 2.2, F);
      float gloss = smoothstep(1.6, 2.6, F);                                               // small wet highlight in the thickest parts
      vec3 o = (vec3(.28,.007,.014)*body + vec3(.25,.015,.020)*thick + vec3(.65,.23,.22)*gloss*.16)*f*smoothstep(1.5,1.3,r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o,body*f*.92);
    }

layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vK;
    void main(){ float u = uTime - aT; if (u < -.35 || u > 0.12){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = clamp(u/0.12, 0., 1.), e = k*k*k;                     // reverse ease-in: holds, then snaps in
      vec3 P = mix(aO, aE, e);
      vec4 mv = viewMatrix*vec4(P, 1.); float S = .07*(1. - .5*e); mv.xy += position.xy*S;
      vP = position.xy; vK = step(0., u)*k + (1. - step(0., u))*(1. + u/.35)*.0; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vK;
    void main(){ float r = length(vP); vec3 o = (uOrange*exp(-r*r*5.) + mix(uGold, vec3(1.), .5)*exp(-r*r*30.))*1.1*smoothstep(1., .8, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
